ee:message.ee:set-payload:
%dw 2.0
output application/json

// 1. Obtenemos el Request Original
var requestOriginal = vars.RequestOrder 

// 2. Función de navegación segura
fun resolvePath(obj: Any, path: String) = 
    if (path != null) 
        path splitBy "." reduce (key, acc = obj) -> acc[key]
    else null

// 3. Construimos el filtro dinámico basado en las reglas
var dynamicMatch = payload.accion.evaluacionRequest reduce (item, acc = {}) -> (
    if (item.parametro != null and item.valor != null)
        do {


             // Resolvemos el valor real del request usando el path elegido
           var valorReal =
    if ((item.parametro default "") == "==" or isEmpty(item.parametro default ""))
        item.comparacion
    else
        resolvePath(requestOriginal, item.parametro)
            // Construimos la llave final (root o dot notation)
            var llaveFinal = if (item.contenedor == "root") item.valor 
                             else (item.contenedor ++ "." ++ item.valor)
// --- LÓGICA DE TRANSFORMACIÓN DE VALOR ---
            var valorFinal = if (item.valor == "_id") 
                                { "\$oid": valorReal } // Si es _id, aplicamos formato ObjectId
                             else if (item.usaRegex == true) 
                                { "\$regex": valorReal } 
                             else 
                                valorReal
            ---
            acc ++ { (llaveFinal): valorFinal }
        }
    else acc
)

---
if(upper(payload.accion.metodo) == "POST"){
	"query": {
    "aggregate": payload.accion.coleccion,
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": dynamicMatch
      }
    ],
    "cursor": {}
  }
}
else if(upper(payload.accion.metodo) == "GET")
  	dynamicMatch
else
{}

%dw 2.0 output application/json
--- { sistema: vars.currentRule.accion.sistema, basePath: p("mongo-db-sapi.base-path"), host: p("mongo-db-sapi.host"), port: p("mongo-db-sapi.port"), method: vars.currentRule.accion.metodo, path: vars.currentRule.accion.path, body: if(upper(vars.currentRule.accion.metodo) == "POST") payload else {}, headers: { "client_secret" : p('mongo-db-sapi.security.client-secret'), "client_id" : p('mongo-db-sapi.security.client-id'), "name": vars.headers.name, "X-CORRELATION-ID": vars.headers."X-CORRELATION-ID", "source": vars.headers.source, "systemId": vars.headers.systemId }, queryParameters:if(upper(vars.currentRule.accion.metodo) == "GET") payload else {}, uriParameters:{
} }

%dw 2.0
output application/json

var requestOriginal = vars.RequestOrder default {}

// 1. Mejora en la función de navegación: agregamos validación de nulo en cada paso
fun resolvePath(obj: Any, path: String) = 
    if (path != null and !isEmpty(path)) 
        path splitBy "." reduce (key, acc = obj) -> 
            if (acc != null) acc[key] else null
    else null

var dynamicMatch = (payload.accion.evaluacionRequest default []) reduce (item, acc = {}) -> (
    // 2. Controlamos que el parámetro no sea nulo antes de procesar
    if (item.parametro != null or item.comparacion != null)
        do {
            var parametroLimpio = item.parametro default ""

            var valorReal = if (parametroLimpio == "==" or parametroLimpio == "")
                                item.comparacion
                            else
                                resolvePath(requestOriginal, parametroLimpio)

            var llaveFinal = if (item.contenedor == "root") item.valor 
                             else ((item.contenedor default "default") ++ "." ++ (item.valor default "key"))

            var valorFinal = if (item.valor == "_id") 
                                { "\$oid": valorReal }
                             else if (item.usaRegex == true) 
                                { "\$regex": valorReal } 
                             else 
                                valorReal
            ---
            // 3. Solo agregamos al match si el valorReal no es nulo para evitar queries inválidas en Mongo
            if (valorReal != null) acc ++ { (llaveFinal): valorFinal }
            else acc
        }
    else acc
)

---
if(upper(payload.accion.metodo default "") == "POST"){
    "query": {
        "aggregate": payload.accion.coleccion,
        "pipeline": [
            { "\$match": dynamicMatch }
        ],
        "cursor": {}
    }
}
else if(upper(payload.accion.metodo default "") == "GET")
    dynamicMatch
else
    {}

%dw 2.0
output application/json

// Importamos la librería de fechas
import * from dw::core::Dates

// 1. Datos de origen (usando tus nombres de variables actuales)
var requestOriginal = vars.RequestOrder 
var mongoResponse = if(vars.requestDataSapi.sistema == "mongo-db-sapi-services") payload default {} else {
	result: [payload]
} 
var validaciones = vars.currentRule.accion.evaluacionRespuesta default []

// --- FUNCIONES CORE ---
fun resolvePath(obj: Any, path: Any, isManual: Boolean = false) = do {
    var isSizeRequest = (path as String) matches /size\(.*\)/
    var cleanPath = if (isSizeRequest) 
                        (path as String) replace "size(" with "" replace ")" with ""
                    else path as String

    var fullPath = if (isManual) cleanPath
                   else if (cleanPath contains "payload.") cleanPath replace "payload." with "" 
                   else if (cleanPath contains "result.") cleanPath
                   else "result[0]." ++ cleanPath
    ---
    do {
        var extractedData = (fullPath as String) splitBy "." reduce (key, acc = obj) -> (
            if (acc == null) null 
            else if (key contains "[") do {
                var parts = key splitBy "["
                var attr = parts[0]
                var index = (parts[1] replace "]" with "") as Number
                ---
                if (acc[attr] != null) acc[attr][index] else null
            } else acc[key]
        )
        ---
        if (isSizeRequest) 
            if (extractedData is Array) sizeOf(extractedData)
            else if (extractedData is Object) sizeOf(keysOf(extractedData))
            else if (extractedData == null) 0
            else 1
        else extractedData
    }
}

fun getExpectedValue(expected: Any) = 
    if (expected != null and expected is String and (expected matches /\{\{.*\}\}/)) do {
        var pathReq = expected replace "{{" with "" replace "}}" with ""
        ---
        (pathReq as String) splitBy "." reduce (key, acc = requestOriginal) -> acc[key]
    }
    else expected

fun checkCondition(actual, operator, expected) = do {
    var a = if (actual != null and !(actual is Array) and !(actual is Object)) trim(actual as String) else actual
    var e = if (expected != null and !(expected is Array) and !(expected is Object)) trim(expected as String) else expected
    ---
    operator match {
        case "exists" -> actual != null
        case "not_exists" -> actual == null
        case "max_30_days" -> do {
            var hoy = now() as Date
            var fechaEvaluar = actual as Date default null
            ---
            if (fechaEvaluar != null) abs(daysBetween(fechaEvaluar, hoy)) <= 30 else false
        }
        case "mayor_hoy" -> do {
	        var hoy = now() as Date
	        var fechaEvaluar = actual as Date default null
	        ---
	        // Si fechaEvaluar es mayor a hoy, daysBetween devuelve un número positivo
	        if (fechaEvaluar != null) (fechaEvaluar > hoy) else false
    	}
        case ">" -> (actual default 0) > (expected default 0)
        case "==" -> upper(a) == upper(e)
        case "!=" -> upper(a) != upper(e)
        case "is_not_empty" -> !isEmpty(actual)
        else -> false
    }
}

// --- PROCESAMIENTO ---
var listaResultados = validaciones map (item) -> do {
    var categoriaRequest = lower(requestOriginal.category default "")
    var pathFinalMongo = if (item.campoResultado contains "{category}")
                            if (categoriaRequest == "lte") 
                                item.campoResultado replace "{category}" with "score_movil"
                            else 
                                item.campoResultado replace "{category}" with "score_fija"
                         else 
                            item.campoResultado

    var isManual = (item.tipoEvaluacion default "") == "MANUAL"
    var valorEnMongo = resolvePath(mongoResponse, pathFinalMongo default "", false)
    var valorAComparar = if (isManual)
                            resolvePath(requestOriginal, item.valorEsperado default "", true)
                         else
                            getExpectedValue(item.valorEsperado)

    var cumpleCondicion = checkCondition(valorEnMongo, item.logica, valorAComparar)
    ---
    {
        descripcion: item.descripcion,
        resultado: if (cumpleCondicion) "OK" else "FALLO",
        comparacion: if (item.logica == "exists") 
                (if (cumpleCondicion) "El objeto existe" else "El objeto NO existe")
             else if (item.logica == "max_30_days")
                "$(valorEnMongo default 'null') no supera los 30 días respecto a hoy"
             else if (item.logica == "mayor_hoy")
                "$(valorEnMongo default 'null') la agenda no es mayor a hoy"
             else 
                "$(upper(valorEnMongo) default 'null') $(item.logica) $(upper(valorAComparar) default 'null')",
        critica: (not cumpleCondicion) and (item.obligatoria default false),
        obligatoria: item.obligatoria
    }
}

// --- SALIDA PARA SET VARIABLE ---
---
 {
 	resultadoRegla :{
        idRegla: vars.currentRule.idRegla default "",
        obligatoria: vars.currentRule.obligatoria default "",
        evaluacionDetallada: listaResultados map (r) -> (r - "critica"),
        esValido: if (isEmpty(listaResultados)) true 
                  else not (listaResultados.critica contains true),
        respuestaRegla: if (not (listaResultados.critica contains true)) vars.currentRule.siSeCumple 
                        else vars.currentRule.siFalla,
        estadoOrdenComercial: vars.currentRule.estadoOrdenComercial,
    },
    resultadoSistema :{
        llave: vars.currentRule.accion.coleccion default "",
        idRegla: vars.currentRule.idRegla default "",
        objeto: payload.result[0] default {}
    }
 }

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
do {
    // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío
    var acumulado = vars.resultadoSapi default []

    // 2. Creamos el objeto de la regla actual
    var resultadoActual = {
        llave: vars.currentRule.accion.coleccion default "",
        idRegla: vars.currentRule.idRegla default "",
        objeto: payload.result[0] default {}
    }
    ---
    // 3. Retornamos la lista con el nuevo elemento al final
    acumulado ++ [resultadoActual]
}
